package cn.huankan.event;
import java.util.*;import java.nio.charset.StandardCharsets;import cn.huankan.evidence.EvidenceService;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;
@Service public class RelationReviewService {
 private final JdbcTemplate db;public RelationReviewService(JdbcTemplate db){this.db=db;}
 public record Review(String decision,String actor,String reason,UUID evidenceId,String excerpt,String limitations){}
 @Transactional public void review(UUID id,Review q){if(q.decision()==null||!Set.of("ACCEPT","REJECT","RETURN_FOR_PROOF").contains(q.decision())||q.actor()==null||q.actor().isBlank()||q.actor().length()>200||q.reason()==null||q.reason().length()<10||q.reason().length()>4000||q.limitations()==null||q.limitations().length()<5)throw new IllegalArgumentException("审核决定、责任人、依据和局限必须填写");var relation=db.queryForMap("SELECT r.*,a.official_name subject,b.official_name object FROM entity_relation r JOIN financial_entity a ON a.id=r.subject_id JOIN financial_entity b ON b.id=r.object_id WHERE r.id=? FOR UPDATE OF r",id);
  Map<String,Object> proof=null;if(q.evidenceId()!=null){proof=db.queryForMap("SELECT r.*,s.level,l.status license_status,l.storage_allowed,l.valid_until FROM raw_evidence r JOIN source_registry s ON s.id=r.source_id JOIN source_license l ON l.source_id=s.id WHERE r.id=?",q.evidenceId());if(q.excerpt()==null||q.excerpt().length()<5||q.excerpt().length()>4000||!new String((byte[])proof.get("raw_content"),StandardCharsets.UTF_8).contains(q.excerpt())||!EvidenceService.hash((byte[])proof.get("raw_content")).equals(proof.get("raw_content_hash")))throw new IllegalArgumentException("关系证据必须为实际原文摘录且哈希完整");}
  if(q.decision().equals("ACCEPT")){if(proof==null||!"L0".equals(proof.get("level"))||!"APPROVED".equals(proof.get("license_status"))||!Boolean.TRUE.equals(proof.get("storage_allowed"))||proof.get("valid_until")!=null&&((java.sql.Timestamp)proof.get("valid_until")).toInstant().isBefore(java.time.Instant.now()))throw new IllegalArgumentException("接受关系需要有效许可的官方证据");String kind=relation.get("relation_kind").toString(),type=relation.get("type").toString();if(!Set.of("BUSINESS_FACT","INDUSTRY_MEMBERSHIP","ACCOUNTING_CONSOLIDATION","LEGAL_IDENTITY").contains(kind))throw new IllegalArgumentException("AI、宏观与统计假设不能升级为真实关系");if(!q.excerpt().contains(relation.get("subject").toString())||!q.excerpt().contains(relation.get("object").toString()))throw new IllegalArgumentException("双方名称未在同一关系证据中被确认");
   Set<String> terms=switch(type){case "CUSTOMER"->Set.of("customer","客户");case "SUPPLIER","UPSTREAM","DOWNSTREAM"->Set.of("supplier","供应商","supplies","供货");case "PARTNER"->Set.of("partnership","合作协议");case "ISSUER"->Set.of("issuer","发行人");case "INDUSTRY"->Set.of("industry classification","行业分类");case "ACCOUNTING_DIRECT_PARENT"->Set.of("IS_DIRECTLY_CONSOLIDATED_BY");case "ACCOUNTING_ULTIMATE_PARENT"->Set.of("IS_ULTIMATELY_CONSOLIDATED_BY");default->Set.of();};String lower=q.excerpt().toLowerCase(Locale.ROOT);if(terms.isEmpty()||terms.stream().noneMatch(x->lower.contains(x.toLowerCase(Locale.ROOT))))throw new IllegalArgumentException("缺少该关系类型的明确披露，名称共现不能接受");if(proof.get("published_at")==null)throw new IllegalArgumentException("首次公开时间尚未取得，关系保持待审核，不能用采集时间替代");
   db.update("UPDATE entity_relation SET status='VERIFIED',evidence_id=?,first_public_at=?,disclosed_at=? WHERE id=?",q.evidenceId(),proof.get("published_at"),proof.get("published_at"),id);
  }else db.update("UPDATE entity_relation SET status=? WHERE id=?",q.decision().equals("REJECT")?"REJECTED":"PENDING",id);
  db.update("INSERT INTO relation_review_history(relation_id,decision,actor,reason,evidence_id,excerpt,limitations) VALUES(?,?,?,?,?,?,?)",id,q.decision(),q.actor(),q.reason(),q.evidenceId(),q.excerpt(),q.limitations());
 }
 public Object history(UUID id){return db.queryForList("SELECT * FROM relation_review_history WHERE relation_id=? ORDER BY created_at DESC,id DESC LIMIT 100",id);}
}
